import java.util.Scanner;

public class Test {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    while (sc.hasNextLine()) {
      sc.nextLine();
      System.out.println(TextDocumentAnalysis.input(sc.nextLine()));
    }
    sc.close();
  }
  public static void main0(String[] args) {
    String[] testInputs = {
      "_Hello_Vasya(and_Petya)__bye_(and_OK)",
      "_a_(_b___c)__de_f(g_)__h__i(j_k_l)m__",
      "(LoooonG)__shOrt__(LoooonG)",
      "(___)",
      "Q(___)_u(_U)HG"
    };
    for (String inputLine : testInputs) {
      String outputLine = TextDocumentAnalysis.input(inputLine);
      System.out.println(outputLine);
    }
  }
}

class TextDocumentAnalysis {
  public static String input(String str) {
    int totalLen = str.length();
    boolean insideBrackets = false;
    int totalWordsCount = 0;
    int maxWordLen = 0;
    int currentWordLen = 0;
    for (int i=0; i<totalLen; i++) {
      char ch = str.charAt(i);
      if (ch == '(') {
        if (currentWordLen > 0) {
          if (currentWordLen > maxWordLen) maxWordLen = currentWordLen;
          currentWordLen = 0;
        }
        insideBrackets = true;
      } else if (ch == ')') {
        if (currentWordLen > 0) {
          totalWordsCount++;
          currentWordLen = 0;
        }
        insideBrackets = false;
      } else if (ch == '_') {
        if (currentWordLen > 0) {
          if (insideBrackets) {
            totalWordsCount++;
          } else {
            if (currentWordLen > maxWordLen) maxWordLen = currentWordLen;
          }
          currentWordLen = 0;
        }
      } else {
        currentWordLen++;
      }
    }
    if (currentWordLen > 0) {
      if (insideBrackets) {
        totalWordsCount++;
      } else {
        if (currentWordLen > maxWordLen) maxWordLen = currentWordLen;
      }
    }
    return maxWordLen + " " + totalWordsCount;
  }
}
